#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.frozenOrb)]
    public class FrozenOrb : EntityBehaviourDefinition, IHellfireIgniteBehaviour, IDeathEffectsBehaviour
    {
        public FrozenOrb(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostProjectileHitCallback);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            var angle = entity.RNG.Next(0, 360f);
            FireBolt(entity, angle);
            if (entity.IsSecondsInterval(0.2f))
            {
                entity.PlaySound(VanillaSoundID.frozenOrb);
            }
        }
        public void DeathEffects(Entity entity, DeathInfo deathInfo)
        {
            IceBlast(entity);
        }
        private void PostProjectileHitCallback(VanillaLevelCallbacks.PostProjectileHitParams args, CallbackResultVoid result)
        {
            var info = args.hit;
            var projectile = info.Projectile;
            if (!projectile.HasBehaviour(this))
                return;
            IceBlast(projectile);
        }
        public void Ignite(Entity entity, Entity hellfire, bool cursed, bool enter)
        {
            var param = entity.GetSpawnParams();
            param.SetProperty(EngineEntityProps.SIZE, entity.GetScaledSize());
            entity.Spawn(VanillaEffectID.smoke, entity.Position, param);
            entity.Die();
            entity.PlaySound(VanillaSoundID.fizz);
        }
        public void FireBolt(Entity orb, float angle)
        {
            var position2D = Vector2.right.RotateClockwise(angle);
            var position = orb.GetCenter() + new Vector3(position2D.x, 0, position2D.y) * (orb.GetScaledSize().x * 0.5f);

            var velocity2D = Vector2.right.RotateClockwise(angle + BOLT_VELOCITY_ANGLE_OFFSET);
            var shotVelocity = orb.GetShotVelocity();
            var velocity = new Vector3(velocity2D.x, 0, velocity2D.y) * shotVelocity.magnitude;

            var boltDamage = orb.GetDamage() * GetBoltDamageMultiplier(orb);

            var projArgs = orb.GetShootParams();
            projArgs.damage = boltDamage;
            projArgs.position = position;
            projArgs.velocity = velocity;
            orb.ShootProjectile(projArgs);
        }
        public void IceBlast(Entity orb)
        {
            var count = GetBlastBoltCount(orb);
            var angleInterval = 360f / count;
            var offset = orb.RNG.Next(0, BOLT_VELOCITY_ANGLE_OFFSET);
            for (int i = 0; i < count; i++)
            {
                var angle = angleInterval * i + offset;
                FireBolt(orb, angle);
            }
        }
        public static int GetBlastBoltCount(Entity entity) => entity.GetProperty<int>(PROP_BLAST_BOLT_COUNT);
        public static void SetBlastBoltCount(Entity entity, int value) => entity.SetProperty(PROP_BLAST_BOLT_COUNT, value);
        public static float GetBoltDamageMultiplier(Entity entity) => entity.GetProperty<float>(PROP_BOLT_DAMAGE_MULTIPLIER);
        public static void SetBoltDamageMultiplier(Entity entity, float value) => entity.SetProperty(PROP_BOLT_DAMAGE_MULTIPLIER, value);
        public static readonly VanillaEntityPropertyMeta<int> PROP_BLAST_BOLT_COUNT = new VanillaEntityPropertyMeta<int>("blast_bolt_count", 16);
        public static readonly VanillaEntityPropertyMeta<float> PROP_BOLT_DAMAGE_MULTIPLIER = new VanillaEntityPropertyMeta<float>("bolt_damage_multiplier", 0.25f);
        public const float BOLT_VELOCITY_ANGLE_OFFSET = 30f;
    }
}
